/**
 * Pure validators for LLM-generated Theater Scorecard data.
 *
 * Extracted so both the generator (runtime guards) and the eval harness
 * (scripts/evals/theater-scorecard-eval.js) call the same code. Tests
 * require() these functions directly — never copy logic into the test file.
 *
 * Theater Scorecard = venueScores object in theater-metadata.json:
 *   { sightlines, sound, comfort, ambiance, facilities, summary, overall, sources, lastResearched }
 *
 * Generated by scripts/research-theater-scores.js via GPT-4o synthesis of
 * SeatPlan, A View From My Seat, and Reddit review data.
 *
 * Known incident: Todd Haimes Theatre shipped "elevator access to all levels"
 * in LLM-generated summary. Accessibility claims must come from the
 * verified accessibility object, not from the model.
 */

'use strict';

// ─── Constants ──────────────────────────────────────────────────────────────

const SCORE_DIMENSIONS = ['sightlines', 'sound', 'comfort', 'ambiance', 'facilities'];

// Max chars for a 1-2 sentence summary. GPT-4o occasionally runs long.
const SUMMARY_WARN_CHARS = 400;
const SUMMARY_MAX_CHARS  = 500;
const SUMMARY_MIN_CHARS  = 40;

// Patterns banned in LLM-generated summary text.
// Accessibility/ADA claims must come from the verified accessibility object.
const BANNED_SUMMARY_PATTERNS = [
  { pattern: /\belevators?\b/i,                         category: 'accessibility', reason: 'elevator claims must come from verified accessibility object, not LLM' },
  { pattern: /\bwheelchair[- ]?(accessible|access|friendly|lift|ramp)?\b/i, category: 'accessibility', reason: 'wheelchair claims need verified source' },
  { pattern: /\bADA[- ]?(compliant|accessible)?\b/,     category: 'accessibility', reason: 'ADA compliance requires legal-grade verification' },
  { pattern: /\bstep[- ]free\b/i,                       category: 'accessibility', reason: 'accessibility claim' },
  { pattern: /\bassistive[- ]listening\b/i,             category: 'accessibility', reason: 'accessibility claim' },
  { pattern: /\bhearing[- ]loop\b/i,                    category: 'accessibility', reason: 'accessibility claim' },
  { pattern: /\b(closed[- ])?caption(ing|ed)?\b/i,     category: 'accessibility', reason: 'accessibility claim' },
  { pattern: /\bservice (animal|dog)\b/i,               category: 'accessibility', reason: 'accessibility claim' },
  // "most accessible house" / "accessible venue" → accessibility claim
  { pattern: /\bmost accessible\b/i,                    category: 'accessibility', reason: 'superlative accessibility claim needs verified source' },
  // Safety — out of scope
  { pattern: /\bfire (exit|escape)\b/i,                 category: 'safety', reason: 'safety infrastructure claims out of scope' },
  { pattern: /\bemergency (exit|evacuation)\b/i,        category: 'safety', reason: 'safety infrastructure claims out of scope' },
];

// Phrases that indicate a show-specific claim rather than a venue-level claim.
// The prompt says "not about any specific show" but GPT sometimes drifts.
const SHOW_REFERENCE_PATTERNS = [
  { pattern: /\bcurrently (playing|running|showing)\b/i, reason: 'references current production, not the venue' },
  { pattern: /\bthis season['']?s\b/i,                   reason: 'season-specific reference' },
  { pattern: /\bfor [A-Z][a-z]+ (and [A-Z][a-z]+)? specifically\b/, reason: 'show-specific reference' },
];

// Phrases that appear verbatim in multiple theater summaries → boilerplate.
// Cross-theater check — requires seeing all theaters together.
const BOILERPLATE_PHRASES = [
  'generally good sightlines',
  'offers generally good sightlines',
  'sound quality is above average',
];

// Unambiguous score-summary contradictions.
// These are tight patterns to avoid false positives — only flag the clearest
// contradictions where the summary directly contradicts the numeric score.
const COMFORT_POSITIVE_PHRASES = [
  /\bspacious seat(ing|s)\b/i,
  /\bexcellent legroom\b/i,
  /\bgreat legroom\b/i,
  /\bample legroom\b/i,
  /\bcomfortable seat(ing|s)\b/i,
  /\bwide seat(ing|s)\b/i,
  /\broomy seat(ing|s)\b/i,
];
const COMFORT_NEGATIVE_PHRASES = [
  /\bcramped\b/i,
  /\btight legroom\b/i,
  /\btight seat(ing|s)\b/i,
  /\bnotoriously tight\b/i,
  /\buncomfortable seat(ing|s)\b/i,
  /\bnarrow seat(ing|s)\b/i,
  /\blimited legroom\b/i,
];
const SIGHTLINES_POSITIVE_PHRASES = [
  /\bexcellent sightlines\b/i,
  /\bgreat sightlines\b/i,
  /\boutstanding sightlines\b/i,
  /\bperfect sightlines\b/i,
];
const SIGHTLINES_NEGATIVE_PHRASES = [
  /\bpoor sightlines\b/i,
  /\bbad sightlines\b/i,
  /\bmany obstructions\b/i,
  /\bsignificant obstructions\b/i,
];

// ─── Validators ─────────────────────────────────────────────────────────────

/**
 * Validate that all required score dimensions are present and in range.
 * Returns array of findings (empty = clean).
 *
 * @param {string} theaterName
 * @param {object} venueScores
 * @returns {Array<{theaterName: string, type: string, field: string, message: string}>}
 */
function validateScoreRange(theaterName, venueScores) {
  const findings = [];
  if (!venueScores || typeof venueScores !== 'object') {
    findings.push({ theaterName, type: 'missing-scores', field: 'venueScores', message: 'venueScores object missing' });
    return findings;
  }
  for (const dim of SCORE_DIMENSIONS) {
    const val = venueScores[dim];
    if (val == null) {
      findings.push({ theaterName, type: 'missing-dimension', field: dim, message: `${dim} dimension missing` });
    } else if (!Number.isInteger(val) || val < 1 || val > 5) {
      findings.push({ theaterName, type: 'score-out-of-range', field: dim, message: `${dim}=${val} is not an integer 1–5` });
    }
  }
  if (venueScores.overall != null) {
    const o = venueScores.overall;
    if (typeof o !== 'number' || o < 1 || o > 5) {
      findings.push({ theaterName, type: 'score-out-of-range', field: 'overall', message: `overall=${o} is out of expected range 1–5` });
    }
  }
  return findings;
}

/**
 * Validate the LLM-generated summary field.
 * Checks: present, length, banned claims, show references.
 *
 * @param {string} theaterName
 * @param {string|undefined} summary
 * @returns {Array<{theaterName: string, type: string, field: string, message: string, matched?: string}>}
 */
function validateSummary(theaterName, summary) {
  const findings = [];

  if (!summary || typeof summary !== 'string' || summary.trim().length === 0) {
    findings.push({ theaterName, type: 'missing-summary', field: 'summary', message: 'summary is missing or empty' });
    return findings;
  }

  if (summary.length < SUMMARY_MIN_CHARS) {
    findings.push({ theaterName, type: 'summary-too-short', field: 'summary', message: `summary is ${summary.length} chars (min ${SUMMARY_MIN_CHARS})` });
  }

  if (summary.length > SUMMARY_MAX_CHARS) {
    findings.push({ theaterName, type: 'summary-too-long', field: 'summary', message: `summary is ${summary.length} chars (max ${SUMMARY_MAX_CHARS})`, matched: summary.slice(0, 80) + '…' });
  } else if (summary.length > SUMMARY_WARN_CHARS) {
    findings.push({ theaterName, type: 'summary-long-warning', field: 'summary', message: `summary is ${summary.length} chars — consider trimming (warn threshold ${SUMMARY_WARN_CHARS})`, matched: summary.slice(0, 80) + '…' });
  }

  for (const rule of BANNED_SUMMARY_PATTERNS) {
    const match = summary.match(rule.pattern);
    if (match) {
      findings.push({
        theaterName,
        type: 'banned-claim',
        category: rule.category,
        field: 'summary',
        message: `${rule.category} claim in LLM summary — ${rule.reason}`,
        matched: match[0],
      });
    }
  }

  for (const rule of SHOW_REFERENCE_PATTERNS) {
    const match = summary.match(rule.pattern);
    if (match) {
      findings.push({
        theaterName,
        type: 'show-reference',
        field: 'summary',
        message: `Summary ${rule.reason}`,
        matched: match[0],
      });
    }
  }

  return findings;
}

/**
 * Check for unambiguous score-vs-summary contradictions.
 * Only flags the clearest contradictions to minimize false positives.
 *
 * @param {string} theaterName
 * @param {object} venueScores  — must include summary
 * @returns {Array<{theaterName: string, type: string, message: string, matched: string}>}
 */
function validateScoreSummaryConsistency(theaterName, venueScores) {
  const findings = [];
  const summary = venueScores && venueScores.summary;
  if (!summary || typeof summary !== 'string') return findings;

  const comfort = venueScores.comfort;
  if (comfort != null) {
    if (comfort >= 4) {
      for (const re of COMFORT_NEGATIVE_PHRASES) {
        const match = summary.match(re);
        if (match) {
          findings.push({ theaterName, type: 'score-summary-conflict', field: 'comfort', message: `comfort=${comfort} (good) but summary says "${match[0]}"`, matched: match[0] });
          break;
        }
      }
    }
    if (comfort <= 2) {
      for (const re of COMFORT_POSITIVE_PHRASES) {
        const match = summary.match(re);
        if (match) {
          findings.push({ theaterName, type: 'score-summary-conflict', field: 'comfort', message: `comfort=${comfort} (poor) but summary says "${match[0]}"`, matched: match[0] });
          break;
        }
      }
    }
  }

  const sightlines = venueScores.sightlines;
  if (sightlines != null) {
    if (sightlines >= 4) {
      for (const re of SIGHTLINES_NEGATIVE_PHRASES) {
        const match = summary.match(re);
        if (match) {
          findings.push({ theaterName, type: 'score-summary-conflict', field: 'sightlines', message: `sightlines=${sightlines} (good) but summary says "${match[0]}"`, matched: match[0] });
          break;
        }
      }
    }
    if (sightlines <= 2) {
      for (const re of SIGHTLINES_POSITIVE_PHRASES) {
        const match = summary.match(re);
        if (match) {
          findings.push({ theaterName, type: 'score-summary-conflict', field: 'sightlines', message: `sightlines=${sightlines} (poor) but summary says "${match[0]}"`, matched: match[0] });
          break;
        }
      }
    }
  }

  return findings;
}

/**
 * Cross-theater: detect boilerplate phrases used verbatim in multiple summaries.
 * Returns warnings — not errors — since some shared phrasing is acceptable.
 *
 * @param {object} theaters  — { [name]: venueScores }
 * @returns {Array<{type: string, phrase: string, count: number, theaters: string[]}>}
 */
function detectBoilerplatePhrases(theaters) {
  const findings = [];
  for (const phrase of BOILERPLATE_PHRASES) {
    const matched = [];
    for (const [name, vs] of Object.entries(theaters)) {
      const s = vs && vs.summary;
      if (s && s.toLowerCase().includes(phrase.toLowerCase())) {
        matched.push(name);
      }
    }
    if (matched.length >= 3) {
      findings.push({
        type: 'boilerplate-phrase',
        phrase,
        count: matched.length,
        theaters: matched,
        message: `"${phrase}" appears verbatim in ${matched.length} theaters — likely canned boilerplate`,
      });
    }
  }
  return findings;
}

/**
 * Cross-theater: score distribution stats for each dimension.
 * Warns when >75% of theaters share the same value (dead distribution).
 *
 * @param {object} theaters  — { [name]: venueScores }
 * @returns {{ stats: object, warnings: Array }}
 */
function checkScoreDistribution(theaters) {
  const stats = {};
  const warnings = [];
  const names = Object.keys(theaters);
  const total = names.length;
  if (total === 0) return { stats, warnings };

  for (const dim of SCORE_DIMENSIONS) {
    const counts = {};
    let present = 0;
    for (const name of names) {
      const val = theaters[name] && theaters[name][dim];
      if (val != null) {
        counts[val] = (counts[val] || 0) + 1;
        present++;
      }
    }
    const values = Object.keys(counts).map(Number).sort();
    const spread = values.length > 0 ? values[values.length - 1] - values[0] : 0;
    stats[dim] = { distribution: counts, spread, present };

    // Warn if >75% clustered at a single value
    for (const [val, cnt] of Object.entries(counts)) {
      const pct = cnt / present;
      if (pct > 0.75) {
        warnings.push({ type: 'score-clustering', dimension: dim, value: Number(val), count: cnt, pct: Math.round(pct * 100), message: `${dim}: ${Math.round(pct * 100)}% of theaters scored ${val} — poor differentiation` });
      }
    }

    // Warn if range is too narrow (all theaters within 1 point of each other)
    if (spread < 2 && present >= 10) {
      warnings.push({ type: 'narrow-spread', dimension: dim, spread, message: `${dim}: scores only span ${spread} point(s) across ${present} theaters — not differentiating` });
    }
  }
  return { stats, warnings };
}

/**
 * Run all per-theater validators on a single venueScores object.
 * Convenience wrapper used by both the eval harness and the generator.
 *
 * @param {string} theaterName
 * @param {object} venueScores
 * @returns {Array} findings (empty = clean)
 */
function validateVenueScores(theaterName, venueScores) {
  return [
    ...validateScoreRange(theaterName, venueScores),
    ...validateSummary(theaterName, venueScores && venueScores.summary),
    ...validateScoreSummaryConsistency(theaterName, venueScores),
  ];
}

module.exports = {
  validateScoreRange,
  validateSummary,
  validateScoreSummaryConsistency,
  detectBoilerplatePhrases,
  checkScoreDistribution,
  validateVenueScores,
  // Exported for tests
  SCORE_DIMENSIONS,
  SUMMARY_MAX_CHARS,
  SUMMARY_WARN_CHARS,
  SUMMARY_MIN_CHARS,
  BANNED_SUMMARY_PATTERNS,
};
